INSERT INTO public.products (product_id, name, brand, description, price, sizes, image_url, stock_quantity, category, colors_general) VALUES
('KVP085', 'Baskets Nike Femme SB Zoom Janoski OG+ Pure Platinum', 'Nike', 'Découvrez l''alliance parfaite entre style streetwear et performance avec ces baskets Nike. Conçues pour les passionnés de skate et les amateurs de mode urbaine, elles séduisent par leur design épuré et leurs lignes intemporelles. Leur construction en cuir et matières synthétiques offre une allure raffinée et une grande durabilité. La couleur Pure Platinum rehaussée de touches Black et Hyper Royal apporte une note moderne et sophistiquée à toutes vos tenues. La semelle vulcanisée procure une excellente sensation de board et une adhérence optimale. Le col rembourré et la languette matelassée garantissent un confort exceptionnel lors de sessions prolongées. Ces baskets incarnent l''esprit novateur de Nike tout en conservant l''authenticité du skateboard. Parfaites pour compléter un look décontracté ou affirmer votre style urbain, elles constituent un choix incontournable.', '95', '["37.5", "38", "38.5", "39", "40", "40.5", "41", "42", "42.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_women_sb_zoom_janoski_og_pure_platinum_black_hyper_royal_6.jpg', '15', 'Femme', '[''blanc'', ''noir'', ''bleu'']'),
('KVP086', 'Baskets Nike Femme SB Zoom Janoski OG+ Coconut Milk', 'Nike', 'Découvrez l''essence du skateboard moderne avec ces baskets Nike d''exception. Alliant performance technique et esthétique raffinée, elles incarnent l''innovation et le style caractéristiques de la marque américaine. Leur construction soignée mêle cuir premium et matières synthétiques pour une durabilité optimale. La couleur Coconut Milk sublimée par des détails Coconut Milk et Light Bone crée une harmonie chromatique élégante et moderne. La semelle vulcanisée offre une sensation de board authentique et une adhérence remarquable sur toutes les surfaces. Le système de laçage optimisé assure un maintien personnalisé, tandis que les renforts stratégiques protègent les zones de forte sollicitation. L''iconique swoosh souligne l''héritage sportif et l''engagement de Nike envers l''excellence. Ces baskets s''adressent aux femmes exigeantes qui recherchent performance et style au quotidien.', '95', '["37.5", "38", "38.5", "39", "40", "40.5", "41", "42", "42.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_women_sb_zoom_janoski_og_coconut_milk_coconut_milk_light_bone_6.jpg', '8', 'Femme', '[''blanc'', ''beige'']'),
('KVP087', 'Baskets Nike Homme Air Max 90 White', 'Nike', 'Découvrez l''une des silhouettes les plus emblématiques de Nike avec cette déclinaison moderne d''un classique intemporel. Ces baskets allient parfaitement héritage et innovation, offrant une expérience unique entre style et performance. La technologie Air Max révolutionnaire dans la semelle procure un amorti exceptionnel et une réactivité optimale à chaque foulée. L''empeigne combine habilement cuir, textile et matières synthétiques pour garantir durabilité et confort. Les lignes fluides et les détails signature, notamment les fenêtres Air visibles au talon, affirment l''identité distinctive du modèle. Le coloris White / White / White apporte une polyvalence remarquable, s''adaptant à tous les styles vestimentaires. La semelle intermédiaire en mousse et la semelle extérieure en caoutchouc assurent stabilité et adhérence durables. Ces baskets incarnent l''esprit novateur de Nike et constituent un choix incontournable pour les hommes à la recherche d''authenticité et de qualité.', '140', '["40", "40.5", "41", "42", "42.5", "43", "44", "44.5", "45", "45.5", "46", "47", "47.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_men_air_max_90_white_white_white_10.jpg', '12', 'Homme', '[''blanc'']'),
('KVP088', 'Baskets Nike Homme Air Max 90 Midnight Navy', 'Nike', 'Redécouvrez l''icône intemporelle de Nike dans une version moderne et raffinée. Ces baskets incarnent parfaitement l''alliance entre héritage sportif et innovation technologique. La célèbre technologie Air Max dans la semelle procure un amorti révolutionnaire et un confort inégalé tout au long de la journée. L''empeigne sophistiquée mêle cuir de qualité, mesh respirant et détails synthétiques pour une durabilité exceptionnelle. Le coloris Midnight Navy / Midnight Navy / White crée une esthétique élégante et polyvalente, parfaite pour toutes les occasions. Les lignes fluides caractéristiques et les fenêtres Air visibles affirment l''identité distinctive de ce modèle légendaire. La construction soignée garantit un maintien optimal, tandis que la semelle extérieure en caoutchouc assure une adhérence fiable. L''iconique swoosh témoigne de l''excellence et de l''innovation Nike. Ces baskets constituent un choix incontournable pour les hommes qui recherchent performance, style et authenticité dans une seule paire.', '140', '["40", "40.5", "41", "42", "42.5", "43", "44", "44.5", "45", "45.5", "46", "47", "47.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_men_air_max_90_midnight_navy_midnight_navy_white_6.jpg', '18', 'Homme', '[''bleu'', ''blanc'']'),
('KVP089', 'Baskets Nike Homme Air Max SC Black', 'Nike', 'Découvrez l''essence du basketball moderne réinterprétée dans un style quotidien avec ces baskets Nike d''exception. Inspirées des codes esthétiques du terrain, elles offrent une silhouette épurée et contemporaine qui séduit par son élégance intemporelle. L''empeigne en cuir véritable garantit une durabilité remarquable et un style sophistiqué, tandis que les détails en mesh assurent une respirabilité optimale. Le coloris Black / Black / Black crée une esthétique minimaliste et polyvalente, parfaite pour toutes les occasions. La semelle intermédiaire en mousse procure un amorti confortable et réactif, idéal pour un usage quotidien prolongé. La semelle extérieure en caoutchouc offre une adhérence fiable et une résistance à l''usure exceptionnelle. L''iconique swoosh Nike affirme l''authenticité et l''héritage sportif de la marque. Ces baskets constituent le choix parfait pour les hommes qui recherchent un style décontracté sans compromis sur la qualité et le confort.', '70', '["40", "40.5", "41", "42", "42.5", "43", "44", "44.5", "45", "45.5", "46", "47", "47.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_men_air_max_sc_black_black_black_9.jpg', '25', 'Homme', '[''noir'']'),
('KVP090', 'Baskets Nike Homme Air Max SC White', 'Nike', 'Redécouvrez un classique moderne avec ces baskets Nike qui allient performance et style urbain. Inspirées de l''univers du basketball, elles offrent une silhouette clean et contemporaine parfaitement adaptée au quotidien. L''empeigne en cuir de qualité supérieure assure durabilité et élégance, complétée par des inserts en mesh pour une respirabilité optimale. Le coloris immaculé White / White / Black apporte une polyvalence remarquable et s''harmonise avec toutes les tenues. La semelle intermédiaire en mousse EVA procure un amorti confortable et réactif, garantissant un bien-être tout au long de la journée. La semelle extérieure en caoutchouc offre une adhérence sûre et une résistance durable. Les détails signature Nike, notamment le swoosh emblématique, témoignent de l''authenticité et de l''héritage sportif de la marque. Ces baskets constituent un choix incontournable pour les hommes qui apprécient le style décontracté sans compromis sur la qualité et le confort. Parfaites pour affirmer un look moderne et intemporel.', '70', '["40", "40.5", "41", "42", "42.5", "43", "44", "44.5", "45", "45.5", "46", "47", "47.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_men_air_max_sc_white_white_black_7.jpg', '22', 'Homme', '[''blanc'', ''noir'']'),
('KVP091', 'Baskets Nike Femme Air Max SC White', 'Nike', 'Découvrez l''alliance parfaite entre style urbain et confort moderne avec ces baskets Nike d''exception. Inspirées de l''univers du basketball, elles incarnent l''élégance décontractée et la performance au quotidien. L''empeigne raffinée mêle cuir premium et mesh technique pour garantir durabilité et respirabilité optimales. Le coloris épuré White / White / Black crée une esthétique intemporelle et polyvalente, s''adaptant parfaitement à tous les styles vestimentaires. La semelle intermédiaire en mousse EVA procure un amorti exceptionnel et une réactivité remarquable à chaque pas. La construction soignée assure un maintien optimal, tandis que la semelle extérieure en caoutchouc offre une adhérence fiable et une longévité exceptionnelle. L''iconique swoosh Nike témoigne de l''authenticité et de l''innovation constante de la marque. Ces baskets s''adressent aux femmes modernes qui recherchent performance et élégance dans une seule paire. Parfaites pour affirmer un style contemporain et dynamique au quotidien.', '70', '["36", "36.5", "37.5", "38", "38.5", "39", "40", "40.5", "41", "42", "42.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_women_air_max_sc_white_white_black_7.jpg', '16', 'Femme', '[''blanc'', ''noir'']'),
('KVP092', 'Baskets Nike Femme Air Max SC Black', 'Nike', 'Redécouvrez l''essence du basketball moderne avec ces baskets Nike qui allient sophistication et performance au quotidien. Conçues pour les femmes actives, elles incarnent parfaitement l''esprit urbain contemporain. L''empeigne en cuir véritable garantit une durabilité exceptionnelle et un style raffiné, complétée par des zones en mesh pour une ventilation optimale. Le coloris élégant Black / Black / Black crée une esthétique minimaliste et polyvalente, parfaite pour toutes les occasions. La semelle intermédiaire en mousse EVA offre un amorti confortable et réactif, idéal pour un usage prolongé. La technologie de construction assure un maintien précis, tandis que la semelle extérieure en caoutchouc procure une adhérence sûre et durable. L''emblématique swoosh Nike affirme l''authenticité et l''héritage sportif de la marque. Ces baskets constituent le choix parfait pour les femmes qui apprécient le style décontracté sans compromis sur la qualité et la performance. Un modèle incontournable qui traverse les tendances.', '70', '["36", "36.5", "37.5", "38", "38.5", "39", "40", "40.5", "41", "42", "42.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_women_air_max_sc_black_black_black_9.jpg', '20', 'Femme', '[''noir'']'),
('KVP093', 'Baskets Nike Femme Court Vision Low White', 'Nike', 'Découvrez l''élégance décontractée avec ces baskets Nike qui réinventent les codes du basketball classique. Inspirées des modèles iconiques des années 80, elles offrent une silhouette épurée et intemporelle parfaitement adaptée au style moderne. L''empeigne en cuir synthétique de qualité assure durabilité et facilité d''entretien, tandis que les perforations stratégiques garantissent une respirabilité optimale. Le coloris immaculé White / White / White crée une esthétique pure et polyvalente qui s''harmonise avec toutes les tenues. La semelle intermédiaire en mousse procure un amorti confortable et léger, idéal pour un usage quotidien. La semelle extérieure en caoutchouc avec motif en chevrons offre une adhérence fiable et une résistance durable. L''iconique swoosh Nike témoigne de l''authenticité et de l''innovation de la marque. Ces baskets s''adressent aux femmes qui recherchent un style casual raffiné sans compromis sur le confort. Parfaites pour affirmer une allure moderne et décontractée.', '65', '["36", "36.5", "37.5", "38", "38.5", "39", "40", "40.5", "41", "42", "42.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_women_court_vision_low_white_white_white_11.jpg', '14', 'Femme', '[''blanc'']'),
('KVP094', 'Baskets Nike Enfant Court Borough Low 2 White', 'Nike', 'Offrez à votre enfant le style intemporel et le confort moderne avec ces baskets Nike d''exception. Inspirées des modèles de basketball classiques, elles allient parfaitement héritage sportif et design contemporain. L''empeigne en cuir synthétique de qualité garantit durabilité et facilité d''entretien, idéale pour l''usage intensif des plus jeunes. Le coloris épuré White / White / White apporte une polyvalence remarquable et s''adapte à toutes les tenues. La construction soignée assure un maintien optimal du pied en croissance, tandis que la doublure textile procure douceur et confort. La semelle intermédiaire en mousse offre un amorti adapté aux activités quotidiennes et aux jeux. La semelle extérieure en caoutchouc avec motif d''adhérence garantit stabilité et résistance à l''usure. L''emblématique swoosh Nike affirme l''authenticité et la qualité de la marque. Ces baskets constituent le choix parfait pour les enfants qui débutent leur collection de sneakers avec un modèle iconique et fiable.', '45', '["27.5", "28", "28.5", "29.5", "30", "31", "31.5", "32", "33", "33.5", "34", "35", "35.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_kids_court_borough_low_2_white_white_white_9.jpg', '30', 'Enfant', '[''blanc'']'),
('KVP095', 'Baskets Nike Enfant Court Borough Low 2 Black', 'Nike', 'Découvrez le style basketball moderne adapté aux plus jeunes avec ces baskets Nike d''exception. Conçues pour allier performance et esthétique, elles incarnent parfaitement l''esprit sportif et urbain de la marque. L''empeigne en cuir synthétique de haute qualité assure une durabilité remarquable et une facilité d''entretien adaptée au rythme de vie des enfants. Le coloris sophistiqué Black / Black / Black crée une esthétique élégante et polyvalente qui s''harmonise avec toutes les tenues. La construction pensée pour les pieds en croissance garantit un maintien optimal et un confort durable. La doublure textile douce procure une sensation agréable, tandis que la semelle intermédiaire en mousse offre un amorti adapté aux activités ludiques et sportives. La semelle extérieure en caoutchouc avec motif spécialisé assure une adhérence sûre et une résistance à l''usure. L''iconique swoosh Nike témoigne de l''authenticité et de la qualité légendaire de la marque. Ces baskets constituent un choix idéal pour initier les enfants au style sneakers avec un modèle fiable et intemporel.', '45', '["27.5", "28", "28.5", "29.5", "30", "31", "31.5", "32", "33", "33.5", "34", "35", "35.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/n/i/nike_kids_court_borough_low_2_black_black_black_8.jpg', '28', 'Enfant', '[''noir'']'),
('KVP096', 'Baskets Converse Unisexe Chuck Taylor All Star Classic Low White', 'Converse', 'Découvrez l''icône intemporelle qui a révolutionné l''univers des baskets depuis 1957. Ces Converse incarnent l''authenticité et l''esprit rebelle qui ont séduit des générations d''artistes, de musiciens et d''individus libres. L''empeigne en toile résistante garantit durabilité et respirabilité, tandis que la doublure textile offre un confort optimal au quotidien. Le coloris classique White / White / White apporte une polyvalence remarquable et s''adapte à tous les styles vestimentaires. La semelle vulcanisée emblématique en caoutchouc assure une adhérence fiable et une flexibilité naturelle. Les œillets métalliques et le laçage traditionnel permettent un ajustement personnalisé. L''emblématique étoile et le logo All Star témoignent de l''héritage légendaire de la marque. Ces baskets unisexes s''adressent à tous ceux qui recherchent authenticité et style intemporel. Parfaites pour exprimer votre personnalité et affirmer votre appartenance à une communauté créative mondiale. Un modèle culte qui traverse les époques sans prendre une ride.', '70', '["35", "36", "36.5", "37", "37.5", "38", "39", "39.5", "40", "41", "41.5", "42", "42.5", "43", "44", "44.5", "45", "46", "46.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/c/o/converse_unisex_chuck_taylor_all_star_classic_low_optical_white_6.jpg', '50', 'Unisexe', '[''blanc'']'),
('KVP097', 'Baskets Converse Unisexe Chuck Taylor All Star Classic Low Black', 'Converse', 'Redécouvrez l''essence même de la culture sneakers avec cette version emblématique qui a marqué l''histoire de la mode urbaine. Ces Converse incarnent l''esprit rebelle et créatif qui a séduit musiciens, artistes et libres penseurs depuis des décennies. L''empeigne en toile de coton robuste assure longévité et confort, tandis que la construction intemporelle garantit un style qui ne se démode jamais. Le coloris sophistiqué Black / Black / Black crée une esthétique minimaliste et polyvalente, parfaite pour toutes les occasions. La semelle vulcanisée signature en caoutchouc blanc procure une adhérence naturelle et une flexibilité optimale. Le système de laçage traditionnel avec œillets métalliques permet un ajustement précis et personnalisé. L''étoile iconique et le patch All Star affirment l''authenticité et l''héritage de cette marque légendaire. Ces baskets unisexes constituent un choix incontournable pour exprimer individualité et appartenance à une communauté créative mondiale. Un modèle culte qui traverse les générations et les tendances.', '70', '["35", "36", "36.5", "37", "37.5", "38", "39", "39.5", "40", "41", "41.5", "42", "42.5", "43", "44", "44.5", "45", "46", "46.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/c/o/converse_unisex_chuck_taylor_all_star_classic_low_black_monochrome_6.jpg', '45', 'Unisexe', '[''noir'']'),
('KVP098', 'Baskets Converse Unisexe Chuck Taylor All Star Classic High White', 'Converse', 'Découvrez la version haute de l''icône absolue qui a défini la culture sneakers moderne. Ces Converse montantes incarnent l''authenticité et l''esprit créatif qui ont inspiré des générations d''artistes et de libres penseurs. L''empeigne haute en toile résistante offre un style distinctif et un maintien de cheville optimal, tandis que la construction légendaire assure durabilité et confort. Le coloris immaculé White / White / White apporte une pureté esthétique et une polyvalence exceptionnelle qui s''harmonise avec tous les looks. La semelle vulcanisée emblématique en caoutchouc garantit adhérence naturelle et flexibilité caractéristique. Le laçage étendu jusqu''à la cheville permet un ajustement personnalisé et affirme le caractère distinctif du modèle. L''étoile iconique et le patch All Star témoignent de l''héritage incontournable de la marque. Ces baskets unisexes s''adressent à tous ceux qui recherchent style authentique et expression personnelle. Parfaites pour affirmer votre individualité tout en rejoignant une communauté créative mondiale. Un classique intemporel qui ne vieillit jamais.', '75', '["35", "36", "36.5", "37", "37.5", "38", "39", "39.5", "40", "41", "41.5", "42", "42.5", "43", "44", "44.5", "45", "46", "46.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/c/o/converse_unisex_chuck_taylor_all_star_classic_high_optical_white_6.jpg', '42', 'Unisexe', '[''blanc'']'),
('KVP099', 'Baskets Converse Unisexe Chuck Taylor All Star Classic High Black', 'Converse', 'Redécouvrez l''essence rebelle et créative avec cette version montante de l''icône qui a révolutionné la culture urbaine. Ces Converse incarnent l''esprit libre et authentique qui a séduit musiciens, artistes et individualistes depuis des générations. L''empeigne haute en toile de coton robuste assure protection et style distinctif, tandis que la construction légendaire garantit durabilité et confort inégalés. Le coloris sophistiqué Black / Black / Black crée une esthétique minimaliste et polyvalente qui s''adapte à toutes les expressions stylistiques. La semelle vulcanisée signature procure l''adhérence naturelle et la flexibilité caractéristiques du modèle. Le système de laçage étendu jusqu''à la cheville permet un ajustement optimal et affirme le caractère iconique des Chuck Taylor. L''étoile emblématique et le patch All Star témoignent de l''héritage incontestable de cette marque légendaire. Ces baskets unisexes constituent un choix incontournable pour exprimer individualité et créativité. Parfaites pour rejoindre une communauté mondiale unie par l''amour de l''authenticité et de l''expression personnelle.', '75', '["35", "36", "36.5", "37", "37.5", "38", "39", "39.5", "40", "41", "41.5", "42", "42.5", "43", "44", "44.5", "45", "46", "46.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/c/o/converse_unisex_chuck_taylor_all_star_classic_high_black_monochrome_6.jpg', '38', 'Unisexe', '[''noir'']'),
('KVP100', 'Baskets Vans Unisexe Old Skool Classic Black', 'Vans', 'Découvrez l''icône intemporelle qui a défini la culture skate et streetwear depuis 1977. Ces Vans incarnent l''authenticité et l''esprit rebelle qui ont séduit des générations de skateurs, musiciens et créatifs. L''empeigne en cuir et toile robuste garantit durabilité exceptionnelle et style authentique, tandis que la construction légendaire assure confort et performance. Le coloris classique Black / White crée un contraste saisissant et une polyvalence remarquable qui s''harmonise avec tous les styles. La semelle waffle emblématique en caoutchouc procure l''adhérence légendaire et la sensation de board caractéristique. Le sidestripe iconique affirme l''identité visuelle unique de la marque californienne. La languette matelassée et le col rembourré offrent confort et maintien optimaux. Ces baskets unisexes s''adressent à tous ceux qui recherchent authenticité et expression créative. Parfaites pour affirmer votre appartenance à la culture alternative et votre passion pour l''individualité. Un modèle culte qui traverse les époques en restant fidèle à ses origines skateboard.', '70', '["35", "36", "36.5", "37", "38", "38.5", "39", "40", "40.5", "41", "42", "42.5", "43", "44", "44.5", "45", "46", "46.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/v/a/vans_unisex_old_skool_black_white_14.jpg', '35', 'Unisexe', '[''noir'', ''blanc'']'),
('KVP101', 'Baskets Vans Unisexe Old Skool Classic True White', 'Vans', 'Redécouvrez l''essence pure de la culture californienne avec cette version immaculée de l''icône skateboard. Ces Vans incarnent l''esprit libre et créatif qui a inspiré des générations d''artistes, de skateurs et de libres penseurs. L''empeigne en toile de coton premium et cuir véritable assure durabilité remarquable et style authentique, tandis que la construction légendaire garantit confort et performance optimaux. Le coloris épuré True White / True White apporte une pureté esthétique et une polyvalence exceptionnelle qui s''adapte à toutes les expressions stylistiques. La semelle waffle signature en caoutchouc procure l''adhérence caractéristique et la sensation de board emblématique. Le sidestripe iconique en relief affirme l''identité visuelle unique de la marque. La languette et le col rembourrés offrent un confort supérieur et un maintien optimal. Ces baskets unisexes constituent un choix incontournable pour exprimer individualité et appartenance à la culture alternative. Parfaites pour affirmer votre style personnel tout en célébrant l''héritage authentique du skateboard californien.', '70', '["35", "36", "36.5", "37", "38", "38.5", "39", "40", "40.5", "41", "42", "42.5", "43", "44", "44.5", "45", "46", "46.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/v/a/vans_unisex_old_skool_true_white_6.jpg', '40', 'Unisexe', '[''blanc'']'),
('KVP102', 'Baskets Vans Unisexe Authentic Classic Black', 'Vans', 'Découvrez l''origine même de la légende Vans avec ce modèle historique qui a lancé la révolution skateboard en 1966. Ces baskets incarnent la pureté originelle et l''authenticité californienne qui ont défini une culture mondiale. L''empeigne en toile de coton robuste et la construction minimaliste assurent durabilité et style intemporel, fidèles à l''esprit originel de la marque. Le coloris sophistiqué Black / Black crée une esthétique épurée et polyvalente qui traverse les époques sans faiblir. La semelle waffle révolutionnaire en caoutchouc procure l''adhérence légendaire qui a fait la réputation de Vans. La simplicité du design, avec ses œillets métalliques et son laçage traditionnel, témoigne de l''approche fonctionnelle et authentique de la marque. L''absence d''artifices superflus souligne la philosophie « Off The Wall » qui caractérise l''esprit rebelle californien. Ces baskets unisexes s''adressent aux puristes qui recherchent l''essence même du skateboard et de la culture alternative. Parfaites pour affirmer votre respect des origines et votre passion pour l''authenticité absolue.', '60', '["35", "36", "36.5", "37", "38", "38.5", "39", "40", "40.5", "41", "42", "42.5", "43", "44", "44.5", "45", "46", "46.5"]', 'https://cdn.etrias.nl/media/cache/product_thumb_md/v/a/vans_unisex_authentic_black_black_6.jpg', '32', 'Unisexe', '[''noir'']'),
